#!/usr/bin/env node
/**
 * C9 release bundle: one directory per release with the version, commit, wheel
 * digest, scorecard metrics, conformance result and SLO report. Generated, not
 * hand-edited.
 *
 * Usage: node scripts/release-bundle.js [--notes-only]
 */
"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const { root } = require("./python-runner");

const version = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8")).version;
const outDir = path.join(root, "docs", "harness", "releases", `v${version}`);
fs.mkdirSync(outDir, { recursive: true });

// The public dependency inventory is a release artifact too: regenerate it from
// the locked trees so a release can never ship notices that predate its
// lockfiles. Failures are fatal here; a stale SBOM is not a release.
execFileSync(process.execPath, [path.join(__dirname, "generate-sbom.js")], {
  cwd: root,
  stdio: "inherit",
});

function readJson(relative, fallback) {
  try {
    return JSON.parse(fs.readFileSync(path.join(root, relative), "utf8"));
  } catch {
    return fallback;
  }
}

const scorecard = readJson("docs/harness/scorecard.json", { dimensions: [] });
const registry = readJson("docs/harness/tool-registry.json", {});
const conformance = readJson("docs/harness/conformance-report.json", {});
const slo = readJson("docs/harness/slo-report.json", {});
const commit = execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim();

const wheels = fs.existsSync(path.join(root, "dist"))
  ? fs.readdirSync(path.join(root, "dist")).filter((name) => name.endsWith(".whl"))
  : [];
const wheel = wheels.sort().pop() || null;
const wheelSha = wheel
  ? crypto.createHash("sha256").update(fs.readFileSync(path.join(root, "dist", wheel))).digest("hex")
  : null;

const report = {
  version,
  commit,
  generatedAt: new Date().toISOString(),
  wheel: wheel ? { name: wheel, sha256: wheelSha } : null,
  tools: { count: registry.toolCount || (registry.tools || []).length, digest: registry.digest || null },
  scorecard: (scorecard.dimensions || []).map((d) => ({
    id: d.id, status: d.status, metric: d.metric || null,
  })),
  conformance: conformance.ok === undefined ? null : {
    ok: conformance.ok, passed: conformance.passed, total: conformance.total,
  },
  slo: slo.runs ? {
    runs: slo.runs,
    latency: slo.latency,
    resume: slo.resume,
    cost: slo.cost,
    failures: slo.failures,
  } : null,
};

fs.writeFileSync(path.join(outDir, "report.json"), JSON.stringify(report, null, 2) + "\n", "utf8");

const measured = report.scorecard.filter((d) => d.status === "measured").length;
const notes = `# Eclipse Harness v${version}

- Commit: \`${commit}\`
- Tools: **${report.tools.count}** (digest \`${report.tools.digest}\`)
- Scorecard: **${measured}/${report.scorecard.length}** dimensions measured from runs
- Conformance: **${report.conformance ? (report.conformance.ok ? "PASS" : "FAIL") : "not run"}** (${report.conformance ? report.conformance.passed : 0}/${report.conformance ? report.conformance.total : 0})
- SLO gate: report at \`slo-report.json\`; gates: \`npm run gate:slo\`
- Wheel: **${wheel || "not built"}**${wheelSha ? `\n  - sha256: \`${wheelSha}\`` : ""}

Generated by \`npm run release:bundle\`. PyPI upload and the git tag are the
operator's step; credentials never live in the repository.
`;
fs.writeFileSync(path.join(outDir, "RELEASE.md"), notes, "utf8");
console.log(`[release] wrote ${path.relative(root, outDir)} (${measured}/${report.scorecard.length} measured)`);
